      de: "Die antike römische Siedlung Emona lag an der Stelle des heutigen Ljubljana und war ein wichtiges Zentrum an der Bernsteinstraße. Heute sind Reste der Stadtmauern und eines frühchristlichen Zentrums im archäologischen Park zu besichtigen.",
