      de: "Die Burg von Ptuj thront über der ältesten Stadt Sloweniens und beherbergt heute umfangreiche Sammlungen zur regionalen Geschichte. Das Bauwerk wurde auf den Fundamenten einer römischen Festung und einer früheren mittelalterlichen Burg errichtet.",
