imageHint: "Ptuj Castle on a hill overlooking the town and Drava river",
    descriptionAdvanced: {
      de: "Die Burg Ptuj thront auf einem Hügel über Ptuj, der ältesten urkundlich erwähnten Stadt Sloweniens, und blickt auf eine fast tausendjährige Geschichte zurück. Die erste schriftliche Erwähnung stammt aus dem Jahr 1132, als die Burg als strategische Festung gegen ungarische Einfälle diente. Im Laufe der Jahrhunderte wechselten die Besitzer, darunter das Erzstift Salzburg und später die Adelsfamilien Leslie und Herberstein, die das Bauwerk von einer mittelalterlichen Festung in ein prächtiges Barockschloss umwandelten. Heute beherbergt die Burg das Regionalmuseum Ptuj-Ormož, das eine der bedeutendsten Sammlungen des Landes präsentiert, darunter historische Musikinstrumente, Tapisserien und barocke Gemälde. Besonders berühmt ist die ethnografische Abteilung, die sich den traditionellen Kurenti-Masken widmet, die Teil des UNESCO-Weltkulturerbes sind. Die Architektur der Burg zeigt Stilelemente von der Romanik über die Gotik bis hin zur Renaissance und dem Barock. Von den Burgmauern aus bietet sich ein beeindruckender Panoramablick auf die roten Dächer der Altstadt und das Drautal.",
      hu: "A Ptuji vár egy dombtetőn magasodik Ptuj felett, amely Szlovénia legrégebbi dokumentált városa, és közel ezeréves történelemre tekint vissza. Első írásos említése 1132-ből származik, amikor a vár stratégiai védőbástyaként szolgált a magyar betörések ellen. Az évszázadok során tulajdonosai gyakran cserélődtek, köztük a Salzburgi Érsekség, majd később a Leslie és Herberstein nemesi családok, akik a középkori erődítményt pompás barokk kastéllyá alakították át. Napjainkban a vár a Ptuj-Ormož Regionális Múzeumnak ad otthont, amely az ország egyik legjelentősebb gyűjteményét mutatja be, beleértve történelmi hangszereket, faliszőnyegeket és barokk festményeket. Különösen híres az etnográfiai részleg, amely az UNESCO szellemi világörökség részét képező hagyományos kurenti maszkokat mutatja be. A vár építészete a romántól a gótikán és a reneszánszon át a barokkig számos stílusjegyet hordoz. A várfalaidról lenyűgöző panoráma nyílik az óváros vörös tetőire és a Dráva-völgyre.",
      ro: "Castelul Ptuj domină de pe o colină orașul Ptuj, cea mai veche așezare atestată documentar din Slovenia, având o istorie de aproape un mileniu. Prima mențiune scrisă datează din anul 1132, când fortăreața servea drept punct strategic de apărare împotriva incursiunilor maghiare. De-a lungul secolelor, proprietarii s-au succedat, printre aceștia numărându-se Arhiepiscopia de Salzburg și ulterior familiile nobiliare Leslie și Herberstein, care au transformat edificiul dintr-o cetate medievală într-un palat baroc somptuos. Astăzi, castelul găzduiește Muzeul Regional Ptuj-Ormož, care prezintă una dintre cele mai valoroase colecții din țară, incluzând instrumente muzicale istorice, tapiserii și picturi baroce. Secția de etnografie este renumită pentru expunerea măștilor tradiționale Kurenti, incluse în patrimoniul mondial UNESCO. Arhitectura castelului îmbină elemente din stilurile romanic, gotic, renascentist și baroc. De pe zidurile fortificației, vizitatorii pot admira o panoramă impresionantă asupra acoperișurilor roșii ale orașului vechi și asupra văii râului Drava.",
      en: "Ptuj Castle stands prominently on a hill overlooking Ptuj, the oldest documented town in Slovenia, with a history spanning nearly a millennium. The first written record of the castle dates back to 1132, when it served as a strategic fortification against Hungarian incursions. Over the centuries, its ownership changed frequently, including the Archdiocese of Salzburg and later the noble Leslie and Herberstein families, who transformed the medieval stronghold into a magnificent Baroque residence. Today, the castle houses the Ptuj-Ormož Regional Museum, showcasing one of the nation's most significant collections, including historical musical instruments, tapestries, and Baroque paintings. The ethnographic department is particularly famous for its display of traditional Kurenti masks, which are part of the UNESCO Intangible Cultural Heritage list. The castle's architecture reflects a blend of Romanesque, Gothic, Renaissance, and Baroque styles. From its ramparts, visitors enjoy a stunning panoramic view of the old town's red roofs and the Drava Valley.",
      es: "El castillo de Ptuj se alza sobre la ciudad más antigua de Eslovenia y cuenta con una historia que se remonta al siglo XI. Hoy alberga importantes colecciones de museos.",
      pt: "O castelo de Ptuj ergue-se sobre a cidade mais antiga da Eslovénia e possui uma história que remonta ao século XI. Hoje alberga importantes coleções de museus.",
      fr: "Le château de Ptuj surplombe la plus ancienne ville de Slovénie et possède une histoire qui remonte au XIe siècle. Il abrite aujourd'hui d'importantes collections muséales.",
    },
