      de: ["Ältester Teil der Quecksilbermine (begonnen 1500)", "Seit 2012 Teil des UNESCO-Weltkulturerbes", "Zweitgrößte Quecksilbermine der Weltgeschichte", "Enthält eine unterirdische Kapelle (Heilige Dreifaltigkeit)", "Quecksilbervorkommen wurden 1490 entdeckt", "Besuchertour führt bis in 50 Meter Tiefe"],
