      en: ["Oldest section of the mercury mine (begun in 1500)", "Inscribed as a UNESCO World Heritage site in 2012", "Historically the world's second-largest mercury mine", "Features a unique underground chapel (Holy Trinity)", "Mercury deposits were first discovered here in 1490", "The visitor tour descends to a depth of 50 meters"],
      es: ["Desarrollado alrededor de 1500", "Patrimonio Mundial de la UNESCO desde 2012", "Segunda mina de mercurio más grande", "Visitable a 300 metros de profundidad"],
