      hu: "A fából készült orosz kápolnát az első világháború alatt orosz hadifoglyok építették társaik emlékére, akik egy lavinában vesztették életüket. A hágóútnál áll, amelyet a foglyoknak szélsőséges körülmények között kellett megépíteniük.",
