      pt: ["Construída em 1916 em estilo ortodoxo russo", "Comemora mais de 300 vítimas da avalanche", "Possui duas características torres em forma de bolbo", "Local de celebrações anuais em honra da amizade esloveno-russa"],
      fr: ["Construite en 1916 dans le style orthodoxe russe", "Commémore plus de 300 victimes de l'avalanche", "Possède deux tours caractéristiques en forme de bulbe", "Lieu de célébrations annuelles en l'honneur de l'amitié slovéno-russe"],
