      fr: ["Possède l'une des tours de château les plus hautes de Slovénie", "Mentionné pour la première fois par écrit en 1230", "Presque totalement détruit pendant la Seconde Guerre mondiale", "A servi aux comtes de Gorizia comme base stratégique"],
