      hu: "Ez a gyönyörűen megőrzött kastély a Snežnik-erdő szélén a teljesen hiteles, 19. századi belső berendezéséről ismert. Festői környezetben, egy kis mesterséges tó partján fekszik, és hű képet ad a nemesség életéről.",
