      es: ["Mencionado por primera vez en documentos en 1269", "Antiguo pabellón de caza de la familia Schönburg-Waldenburg", "Uno de los pocos castillos de Eslovenia con mobiliario original", "En medio de un extenso parque paisajista inglés"],
      pt: ["Mencionado pela primeira vez em documentos em 1269", "Antigo pavilhão de caça da família Schönburg-Waldenburg", "Um dos poucos castelos na Eslovénia com mobiliário original", "No meio de um extenso parque paisagístico inglês"],
      fr: ["Mentionné pour la première fois dans des documents en 1269", "Ancien pavillon de chasse de la famille Schönburg-Waldenburg", "L'un des rares châteaux de Slovénie avec des meubles d'origine", "Au milieu d'un vaste parc paysager anglais"],
