imageHint: "Renaissance castle with four corner towers in a forest",
    descriptionAdvanced: {
      de: "Schloss Bogenšperk, eines der bedeutendsten Kulturdenkmäler Sloweniens, liegt im zentralen Teil des Landes nahe der Stadt Litija. Die heutige Renaissance-Anlage wurde im frühen 16. Jahrhundert nach dem großen Erdbeben von 1511 auf den Ruinen einer älteren Festung errichtet. Weltberühmt wurde das Schloss durch den Universalgelehrten Johann Weichard von Valvasor, der es 1672 erwarb und dort zwanzig Jahre lang lebte und arbeitete. Valvasor richtete hier eine Druckerei und eine Kupferstecherei ein, in der er sein monumentales Werk 'Die Ehre des Hertzogthums Crain' vorbereitete. Die Architektur ist durch vier Ecktürme gekennzeichnet, die einen zentralen Innenhof umschließen, was typisch für den Übergang von der Gotik zur Renaissance ist. Heute beherbergt das Schloss mehrere Museen, die sich mit der Geodäsie, dem Leben Valvasors und der Geschichte der Hexerei befassen. Es dient zudem als beliebtes Kulturzentrum für Hochzeiten und Veranstaltungen.",
      hu: "A Bogenšperk-kastély Szlovénia középső részén, Litija közelében található, és az ország egyik legfontosabb reneszánsz műemléke. A mai épület az 1511-es nagy földrengés után épült egy korábbi erődítmény alapjain, négy jellegzetes saroktoronnyal ellátott stílusban. A kastély hírnevét Janez Vajkard Valvasor polihisztornak köszönheti, aki 1672-ben vásárolta meg az ingatlant, és két évtizeden át itt élt. Valvasor a falak között alapította meg az ország első rézmetsző műhelyét és nyomdáját, ahol fő művét, a 'Krajna hercegség dicsőségét' szerkesztette. Az épület építészeti stílusa hűen tükrözi a gótika és a reneszánsz közötti átmenetet a központi udvarral és a bástyákkal. Jelenleg több tematikus kiállításnak ad otthont, amelyek a térképészetet, Valvasor munkásságát és a régió néprajzát mutatják be. A kastély fontos kulturális helyszín és népszerű esküvői központ is egyben.",
      ro: "Castelul Bogenšperk, situat în inima Sloveniei lângă Litija, reprezintă unul dintre cele mai importante centre culturale și istorice ale regiunii Carniola. Construcția actuală în stil renascentist a fost ridicată în secolul al XVI-lea, pe ruinele unei fortificații mai vechi distruse de cutremurul din 1511. Faima internațională a castelului este strâns legată de savantul Janez Vajkard Valvasor, care a locuit aici între 1672 și 1692. În această perioadă, Valvasor a înființat în incinta castelului un atelier de gravură în cupru și o tipografie, unde a redactat enciclopedia sa monumentală 'Slava Ducatului Carniolei'. Arhitectura este definită prin patru turnuri de colț impunătoare care încadrează o curte interioară spațioasă, oferind protecție și eleganță. Astăzi, castelul găzduiește colecții muzeale dedicate geodeziei, cartografiei și superstițiilor populare locale. Este recunoscut ca fiind un centru de excelență pentru conservarea patrimoniului intelectual sloven.",
      en: "Bogenšperk Castle, situated near Litija in central Slovenia, is one of the nation's most significant cultural monuments of the Renaissance era. The current structure was built in the early 16th century following the devastating earthquake of 1511, replacing an older fortification on the same site. The castle achieved historical fame through the work of the polymath Janez Vajkard Valvasor, who owned the estate from 1672 to 1692. Valvasor established a copper-engraving workshop and a printing press within the castle walls, where he produced his magnum opus, 'The Glory of the Duchy of Carniola'. The building's layout features four prominent corner towers surrounding a central courtyard, a hallmark of transitional military and residential architecture. Today, it serves as a museum with exhibitions focused on surveying, Valvasor’s scientific achievements, and regional folklore. The castle remains a vibrant cultural hub, hosting numerous formal ceremonies and educational events throughout the year.",
      es: "El castillo de Bogenšperk está estrechamente vinculado al erudito Janez Vajkard Valvasor. Aquí escribió su famosa obra 'La gloria del ducado de Carniola'.",
      pt: "O castelo de Bogenšperk está estreitamente ligado ao estudioso Janez Vajkard Valvasor. Aqui escreveu a sua famosa obra 'A Glória do Ducado de Carniola'.",
      fr: "Le château de Bogenšperk est étroitement lié à l'érudit Janez Vajkard Valvasor. Il y a écrit son célèbre ouvrage 'La Gloire du duché de Carniole'.",
    },
    factsAdvanced: {
      de: ["Bau der heutigen Anlage begann nach dem Erdbeben von 1511", "Johann Weichard von Valvasor kaufte das Schloss im Jahr 1672", "Sitz der ersten Kupferstecherei auf slowenischem Boden", "Valvasor vollendete hier 1689 sein 3532-seitiges Hauptwerk", "Das Schloss verfügt über vier charakteristische Ecktürme", "Beherbergt heute ein Museum für Geodäsie und Landkarten"],
      hu: ["A jelenlegi épület az 1511-es földrengés után épült", "Janez Vajkard Valvasor 1672-ben lett a kastély tulajdonosa", "Itt működött az első szlovén rézmetsző és nyomda műhely", "Valvasor 1689-ben fejezte be itt 3532 oldalas főművét", "Az épület négy bástyával körülvett belső udvaros elrendezésű", "Ma geodéziai és térképészeti múzeumnak ad otthont"],
      ro: ["Construcția actuală a început după cutremurul din 1511", "Janez Vajkard Valvasor a cumpărat domeniul în anul 1672", "A găzduit primul atelier de gravură în cupru din Slovenia", "Enciclopedia 'Slava Ducatului Carniolei' a fost tipărită în 1689", "Castelul prezintă o arhitectură cu patru turnuri de colț", "Include o expoziție rară despre istoria magiei și superstițiilor"],
      en: ["Current structure was built after the 1511 earthquake", "Janez Vajkard Valvasor purchased the castle in 1672", "Home to the first copper-engraving workshop in Slovenia", "Valvasor finished his 3,532-page encyclopedia here in 1689", "The architecture features four distinct corner defense towers", "Now houses a specialized museum for geodesy and cartography"],
      es: ["Periodo de construcción en el siglo XVI", "Lugar de trabajo de Valvasor", "Famoso taller de grabado en cobre", "Arquitectura renacentista"],
      pt: ["Período de construção no século XVI", "Local de trabalho de Valvasor", "Famosa oficina de gravura em cobre", "Arquitetura renascentista"],
      fr: ["Période de construction au XVIe siècle", "Lieu de travail de Valvasor", "Célèbre atelier de gravure sur cuivre", "Architecture Renaissance"],
    },
    image: "/poi-images/slovenia-bogensperk-castle-history-v2.webp",
