      ro: ["Sit-ul a fost descoperit accidental în anul 1952", "Monumentele funerare datează din secolele II și III d.Hr.", "Cel mai înalt monument depășește înălțimea de 8 metri", "Toate sculpturile sunt realizate din marmură de Pohorje", "Reliefurile înfățișează familia Ennius și scene mitologice", "Necropola a fost conservată sub aluviunile râului Savinja"],
      en: ["Discovered accidentally during field work in 1952", "The funerary monuments date to the 2nd and 3rd centuries AD", "The tallest monument stands over 8 meters high", "Sculpted from high-quality white Pohorje marble", "Features reliefs of the Ennius family and mythological tales", "The site was preserved for centuries under Savinja river silt"],
