      pt: ["Fundado em 1234 por Bernardo de Spanheim", "Possui um pátio arcado com 82 pilares de pedra", "Palco do simpósio internacional de escultura Forma Viva", "A igreja do mosteiro é uma obra-prima do gótico inicial"],
      fr: ["Fondé en 1234 par Bernard de Spanheim", "Possède une cour à arcades avec 82 piliers en pierre", "Lieu du symposium international de sculpture Forma Viva", "L'église du monastère est un chef-d'œuvre du premier gothique"],
