      pt: "As ruínas do castelo de Smlednik erguem-se sobre uma colina acima do rio Sava. Foi um importante posto estratégico na Idade Média.",
      fr: "Les ruines du château de Smlednik surplombent une colline au-dessus de la rivière Sava. C'était un poste stratégique important au Moyen Âge.",
