      hu: "Ez a Karavankák területén található rom egy komplex védelmi rendszer része volt. A maradványok a feudális építészet tipikus vonásait mutatják.",
      ro: "Această ruină din zona Karavankelor a făcut parte dintr-un sistem defensiv complex. Rămășițele prezintă trăsături tipice ale arhitecturii feudale.",
