      es: ["La iglesia fue construida en el siglo XIV.", "Los frescos datan de 1450.", "El altar mayor fue creado en 1680.", "La iglesia mide 18 metros de largo y 9 de ancho.", "El campanario mide 20 metros de altura.", "Situada a 550 metros sobre el nivel del mar."],
      pt: ["A igreja foi construída no século XIV.", "Os frescos datam de 1450.", "O altar-mor foi criado em 1680.", "A igreja mede 18 metros de comprimento e 9 de largura.", "A torre do sino tem 20 metros de altura.", "Situada a 550 metros acima do nível do mar."],
