    imageHint: "Frajstajn castle manor",
    descriptionAdvanced: {
      de: "Das Schloss Frajštajn, gelegen in Zgornja Polskava, ist ein prächtiges Renaissance-Anwesen, das im 16. Jahrhundert errichtet wurde. Ursprünglich als befestigtes Herrenhaus geplant, diente es der Sicherung der landwirtschaftlichen Erträge und als Wohnsitz für den niederen Adel. Die Architektur ist durch einen rechteckigen Grundriss mit vier markanten Ecktürmen gekennzeichnet, was dem Bauwerk ein wehrhaftes und zugleich elegantes Aussehen verleiht. Im 17. und 18. Jahrhundert wurde das Schloss mehrfach umgestaltet, wobei barocke Elemente in die Fassade und das Interieur integriert wurden. Das Schloss war über lange Zeit im Besitz der Familie Tattenbach, die den Ausbau der Gartenanlagen und der Wirtschaftsgebäude vorantrieb. Trotz einiger Vernachlässigungen im 20. Jahrhundert sind die strukturelle Integrität und viele ornamentale Details an den Fensterrahmen und Portalen erhalten geblieben. Heute ist Frajštajn ein wichtiges lokales Kulturdenkmal, das die Entwicklung der Herrenhaus-Architektur im Übergang von der Renaissance zum Barock in Slowenien dokumentiert.",
      hu: "A Zgornja Polskava területén található Frajštajn-kastély egy figyelemre méltó reneszánsz stílusú épületegyüttes, amely a 16. század közepén nyerte el alapvető formáját. Az épületet eredetileg védelmi funkciókkal is ellátták, hogy megvédje a birtokot és a lakóit a korabeli zavargások idején. A kastély alaprajza négyszögletes, sarkaiban zömök tornyok emelkednek, amelyek a korszak erődített udvarházainak jellegzetességei. A 17. század folyamán a Tattenbach család tulajdonába került, akik barokk stílusban alakították át a belső tereket és díszesebb külsőt adtak a homlokzatnak. A kastély körüli egykori park és a gazdasági épületek a környék mezőgazdasági jelentőségét mutatják. Bár a második világháború után az állapota leromlott, az elmúlt évtizedekben több felújítási munkálat is zajlott, hogy megmentsék ezt a történelmi emléket. Frajštajn ma is a régió egyik legfontosabb nemesi laka, amely bepillantást enged a kora újkori Szlovénia társadalmi és építészeti életébe.",
      ro: "Castelul Frajštajn, situat în localitatea Zgornja Polskava, este un conac nobiliar reprezentativ pentru stilul Renașterii târzii, fiind construit în secolul al XVI-lea. Inițial, edificiul a fost conceput ca o structură fortificată pentru a proteja resursele domeniului agricol înconjurător împotriva incursiunilor străine. Arhitectura sa se remarcă prin planul rectangular simetric, flancat de patru turnuri de colț proeminente care îi conferă un aer impunător. În secolul al XVII-lea, proprietatea a fost achiziționată de familia Tattenbach, care a inițiat o serie de modificări baroce, adăugând elemente decorative rafinate fațadei și portalurilor. Interiorul castelului a păstrat parțial structura originală a tavanelor și a scărilor monumentale, reflectând gustul estetic al epocii. De-a lungul secolelor, Frajštajn a servit drept centru administrativ local și reședință de vară pentru aristocrație. În prezent, castelul este protejat ca patrimoniu cultural și reprezintă un punct de interes major pentru studiul arhitecturii civile din estul Sloveniei.",
      en: "Frajštajn Castle, located in Zgornja Polskava, is a notable Renaissance manor built during the 16th century. It was originally designed as a fortified residential building to provide both comfort for the nobility and protection for the estate's agricultural wealth. The castle's architecture features a characteristic rectangular floor plan with four sturdy corner towers, a hallmark of fortified manors in the region during that era. In the 17th century, the castle became the property of the Tattenbach family, who introduced Baroque elements to the interior and facade decorations. Over the years, the manor played a central role in the local economy and social hierarchy. Although it faced periods of neglect in the 20th century, recent restoration efforts have highlighted its historical significance and architectural beauty, particularly its ornate window frames and portals. Today, Frajštajn Castle serves as a vital cultural monument, illustrating the transition from late Renaissance to Baroque residential architecture in Slovenia.",
      es: "El castillo de Frajštajn, también conocido como palacio Frajštajn, se encuentra en el municipio de Zgornja Polskava, Eslovenia. Construido en el siglo XII, sirvió como un punto estratégico vital a lo largo de la ruta comercial entre Estiria y Carintia. A lo largo de los siglos cambió de dueño varias veces, pasando por las familias de Polskava y los condes de Attems. Tras sufrir graves daños en la Segunda Guerra Mundial, fue restaurado parcialmente en los años 50. Su arquitectura combina elementos románicos y góticos con añadidos renacentistas posteriores. El torreón ofrece vistas panorámicas del campo de Drava.",
      pt: "O castelo de Frajštajn, também conhecido como palácio Frajštajn, encontra-se no município de Zgornja Polskava, na Eslovénia. Construído no século XII, serviu como um ponto estratégico vital ao longo da rota comercial entre a Estíria e a Caríntia. Ao longo dos séculos mudou de proprietário várias vezes, passando pelas famílias de Polskava e os condes de Attems. Após sofrer graves danos na Segunda Guerra Mundial, foi restaurado parcialmente nos anos 50. A sua arquitetura combina elementos românicos e góticos com adições renascentistas posteriores. A torre de menagem oferece vistas panorâmicas do campo de Drava.",
      fr: "Le château de Frajštajn, également connu sous le nom de palais Frajštajn, est situé dans la municipalité de Zgornja Polskava, en Slovénie. Construit au XIIe siècle, il a servi de point stratégique vital le long de la route commerciale entre la Styrie et la Carinthie. Au fil des siècles, il a changé plusieurs fois de propriétaire, passant par les familles de Polskava et les comtes d'Attems. Après avoir subi de graves dommages pendant la Seconde Guerre mondiale, il a été partiellement restauré dans les années 50. Son architecture combine des éléments romans et gothiques avec des ajouts Renaissance ultérieurs. Le donjon offre une vue panoramique sur la campagne de Drava.",
    },
