      ro: ["Castelul a fost ridicat în jurul anului 1570 ca reședință nobiliară", "Cele patru turnuri de colț aveau rol defensiv și decorativ", "Familia Tattenbach a deținut proprietatea începând cu secolul XVII", "Portalul principal este decorat cu blazoane sculptate în piatră", "Structura a suferit modificări majore în perioada barocă timpurie", "Situl este clasificat ca monument cultural de importanță locală"],
      en: ["The manor was constructed around 1570 in the Renaissance style", "It features four prominent corner towers designed for defense", "The Tattenbach family was the most notable historical owner", "Decorative Baroque elements were added to the windows in the 1700s", "The building serves as a prime example of a fortified manor (graščina)", "It is a key historical site within the Zgornja Polskava municipality"],
      es: ["Construido en el siglo XII (aprox. 1160)", "Altura del torreón: 25 metros", "Espesor del muro hasta 3 metros", "Reforma en estilo renacentista en 1560", "Propietarios: señores de Polskava (siglos XIII-XV)", "Restauración tras daños de guerra en 1952"],
      pt: ["Construído no século XII (aprox. 1160)", "Altura da torre de menagem: 25 metros", "Espessura da parede até 3 metros", "Reforma em estilo renascentista em 1560", "Proprietários: senhores de Polskava (séculos XIII-XV)", "Restauração após danos de guerra em 1952"],
      fr: ["Construit au XIIe siècle (env. 1160)", "Hauteur du donjon : 25 mètres", "Épaisseur du mur jusqu'à 3 mètres", "Rénovation en style Renaissance en 1560", "Propriétaires : seigneurs de Polskava (XIIIe-XVe siècles)", "Restauration après les dommages de guerre en 1952"],
