    imageHint: "Ribnica castle buildings",
    descriptionAdvanced: {
      de: "Das Schloss Ribnica, im Herzen der gleichnamigen Stadt gelegen, ist ein beeindruckendes Beispiel für die Entwicklung von einer mittelalterlichen Festung zu einem Renaissance-Schloss. Die ursprüngliche Burg wurde bereits im 11. Jahrhundert von den Herren von Reifnitz errichtet und im 16. Jahrhundert umfassend im Renaissancestil umgebaut, um Schutz gegen die osmanischen Einfälle zu bieten. Die Anlage besteht aus einem weitläufigen Innenhof, der von hohen Mauern und Wehrtürmen umgeben ist, wobei die Schlosskapelle eines der architektonischen Highlights darstellt. Im Laufe der Geschichte wechselte das Schloss mehrfach seine Besitzer, darunter die einflussreichen Familien Lamberg und Auersperg. Während des Zweiten Weltkriegs wurde das Schloss schwer beschädigt und brannte fast vollständig aus, doch umfangreiche Restaurierungsarbeiten in den 1950er und 60er Jahren retteten die Anlage. Heute beherbergt das Schloss Ribnica das Museum von Ribnica, eine Galerie und einen Park mit Skulpturen, was es zum kulturellen Mittelpunkt der Region macht. Besonders bekannt ist das Schloss auch für seine Handwerkstraditionen, die in den Ausstellungen dokumentiert sind.",
      hu: "A Ribnica városában található vár Szlovénia egyik legjelentősebb kulturális központja, amelynek története a 11. századig nyúlik vissza. Az eredeti erődítményt a Reifnitz lovagok építették, majd a 16. században, a török veszély idején, jelentős reneszánsz stílusú átalakításokon esett át. A várudvart vastag falak és bástyák veszik körül, amelyek egykor a környék lakosságának nyújtottak menedéket. Az évszázadok során a Lamberg és Auersperg családok is birtokolták a várat, folyamatosan bővítve annak épületeit és gazdasági egységeit. A második világháború alatt az épület súlyos károkat szenvedett, egy bombázás után leégett, de a háború utáni gondos restaurálásnak köszönhetően ma ismét régi fényében tündököl. A várban jelenleg helytörténeti múzeum, galéria és szabadtéri színház működik, a várárok helyén pedig egy gondozott park található szobrokkal. Ribnica vára nemcsak történelmi emlék, hanem az élénk kézműves hagyományok, például a fafaragás és edénykészítés bemutatóhelye is.",
      ro: "Castelul Ribnica, situat în centrul orașului omonim, reprezintă un pilon central al istoriei și culturii din sudul Sloveniei. Primele structuri defensive au fost ridicate în secolul al XI-lea, însă forma actuală de castel renascentist a fost cristalizată în secolul al XVI-lea pentru a face față amenințării otomane. Complexul este format dintr-o curte interioară spațioasă, protejată de ziduri înalte și turnuri de apărare circulare. De-a lungul timpului, castelul a fost în posesia unor familii nobiliare de prestigiu, precum Lamberg și Auersperg, care au influențat dezvoltarea economică a întregii regiuni. În timpul celui de-al Doilea Război Mondial, castelul a fost grav avariat, suferind un incendiu devastator în 1944. Restaurările postbelice au transformat complexul într-un centru cultural vibrant, care găzduiește astăzi Muzeul din Ribnica, o galerie de artă și o scenă pentru spectacole în aer liber. Castelul este renumit și pentru promovarea meșteșugurilor tradiționale locale, în special prelucrarea lemnului și olăritul, care au o tradiție de peste 500 de ani în această zonă.",
      en: "Ribnica Castle, located in the center of the town of Ribnica, is a significant historical site that evolved from a medieval fortress into a Renaissance manor. The original fortification was built in the 11th century by the Lords of Reifnitz and was majorly reconstructed in the 16th century to defend against Ottoman raids. The complex features a large central courtyard enclosed by high defensive walls and towers, with a beautifully restored castle chapel. Historically, it was held by prominent noble families like the Lambergs and Auerspergs, who shaped the town's administrative history. The castle suffered extensive damage during World War II, being nearly destroyed by fire in 1944, but was carefully restored in the following decades. Today, it serves as the cultural heart of Ribnica, housing a regional museum, an art gallery, and a sculpture park. The site is particularly famous for its connection to local artisan traditions, such as woodcraft and pottery, which are prominently featured in its exhibitions.",
      es: "El castillo de Ribnica (Grad Ribnica) es un complejo medieval en la ciudad de Ribnica, Eslovenia. La primera mención data de 1263. Fue construido sobre una colina sobre la ciudad para proteger las rutas comerciales a Croacia. En el siglo XV se amplió en estilo gótico tardío. En el siglo XVII pasó a manos de los condes de Auersperg, quienes lo remodelaron en estilo barroco. Fue dañado durante la Segunda Guerra Mundial, pero tras la guerra fue restaurado y hoy alberga un museo de artesanía en madera e historia regional. La arquitectura es una mezcla de gótico y barroco. El patio con arcadas es especialmente notable. El castillo es un centro cultural y lugar de celebraciones.",
      pt: "O castelo de Ribnica (Grad Ribnica) é um complexo medieval na cidade de Ribnica, Eslovénia. A primeira menção data de 1263. Foi construído sobre uma colina acima da cidade para proteger as rotas comerciais para a Croácia. No século XV foi ampliado no estilo gótico tardio. No século XVII passou para as mãos dos condes de Auersperg, que o remodelaram no estilo barroco. Foi danificado durante a Segunda Guerra Mundial, mas após a guerra foi restaurado e hoje alberga um museu de artesanato em madeira e história regional. A arquitetura é uma mistura de gótico e barroco. O pátio com arcadas é especialmente notável. O castelo é um centro cultural e local de celebrações.",
      fr: "Le château de Ribnica (Grad Ribnica) est un complexe médiéval dans la ville de Ribnica, en Slovénie. La première mention date de 1263. Il a été construit sur une colline surplombant la ville pour protéger les routes commerciales vers la Croatie. Au XVe siècle, il a été agrandi dans le style gothique tardif. Au XVIIe siècle, il est passé aux mains des comtes d'Auersperg, qui l'ont remodelé dans le style baroque. Il a été endommagé pendant la Seconde Guerre mondiale, mais a été restauré après la guerre et abrite aujourd'hui un musée de l'artisanat du bois et de l'histoire régionale. L'architecture est un mélange de gothique et de baroque. La cour à arcades est particulièrement remarquable. Le château est un centre culturel et un lieu de célébrations.",
    },
